/** The package's WebAssembly, inlined by esbuild's binary loader. */
declare module 'ua-cryptography/ua_cryptography_bg.wasm' {
  const bytes: Uint8Array;
  export default bytes;
}

/** Generated by build.mjs from assets/certificates: each file as base64. */
declare module 'bundled-certificates' {
  export const ROOTS: ReadonlyArray<{ name: string; base64: string }>;
  export const INTERMEDIATES: ReadonlyArray<{ name: string; base64: string }>;
}
